// Parse a books.toscrape.com listing page into structured items.
// books.toscrape.com is a sandbox built specifically for scraper practice —
// stable markup, no auth, and explicitly fine to scrape. Each book renders as:
//   <article class="product_pod"> ... <h3><a href="..." title="Book Title">...</a></h3>
//   <p class="price_color">£51.77</p> <p class="instock availability"> In stock </p> ...
//
// Reliability note: HTML scraping is inherently brittle — any site can change
// its markup without warning. So this parser does NOT assume success. It reports
// what it found, and the validation node downstream treats "zero items" as
// "the scraper likely broke," not "there's nothing here" — see the README.

const body = $input.first().json;
const html = (body && (body.data || body.body)) || '';

if (typeof html !== 'string' || html.length < 500) {
  return [{ json: { parseError: true, reason: 'Fetched page empty or too short', items: [] } }];
}

// Split into per-product blocks so a malformed one book can't swallow the rest.
const blocks = html.split('class="product_pod"').slice(1);

const items = [];
for (const block of blocks) {
  // Title lives in: <h3><a href="..." title="THE TITLE">
  const titleM = block.match(/<h3>\s*<a[^>]*title="([^"]+)"/);
  // Relative product URL in that same anchor's href.
  const hrefM = block.match(/<h3>\s*<a[^>]*href="([^"]+)"/);
  // Price e.g. <p class="price_color">£51.77</p>
  const priceM = block.match(/price_color[^>]*>\s*([^<]+?)\s*</);
  // Availability e.g. <p class="instock availability"> In stock </p>
  const stockM = block.match(/instock availability[^>]*>([\s\S]*?)<\/p>/);

  if (!titleM) continue; // no title = not a real product block, skip

  const title = titleM[1].replace(/&amp;/g, '&').trim();
  let url = hrefM ? hrefM[1] : null;
  if (url && !/^https?:\/\//.test(url)) {
    // relative -> absolute (listing hrefs look like 'catalogue/....html')
    url = 'https://books.toscrape.com/' + url.replace(/^(\.\.\/)+/, '');
  }
  const price = priceM ? priceM[1].trim() : null;
  const inStock = stockM ? /in stock/i.test(stockM[1]) : null;

  items.push({ title, url, price, inStock });
}

return [{ json: { parseError: false, totalParsed: items.length, items } }];

// The reliability gate — the whole point of this demo.
// Two outcomes that look identical downstream but mean opposite things:
//   (a) scraper BROKE (parse error, or zero items when the page clearly has some)
//       -> route to the ALERT path so a human is told
//   (b) scraper WORKED, there just wasn't much to report
//       -> normal output path
// Conflating these is the classic silent failure: a scraper that quietly
// returns nothing after the site's markup changes, while everyone assumes
// "no news." We refuse to conflate them.

const d = $input.first().json;

if (d.parseError || !Array.isArray(d.items) || d.items.length === 0) {
  return [{ json: {
    scraperOk: false,
    reason: d.reason || 'Parsed zero items — page markup may have changed',
    items: [],
  } }];
}

return [{ json: {
  scraperOk: true,
  totalParsed: d.items.length,
  items: d.items,
} }];

// Demo endpoint: just surface the parsed data. In a real build this is where
// a delivery step goes (email/Slack/Sheet). Kept as plain output so anyone can
// import and run this with zero credentials.
const d = $input.first().json;
return [{ json: {
  status: 'ok',
  count: d.totalParsed,
  sample: d.items.slice(0, 5),
  allItems: d.items,
} }];

// Loud failure. Both the HTTP-error output and the failed-validation branch
// land here. In a real build this fires a Slack/email alert; in the demo it
// simply emits a clearly-flagged object so the broken path is unmistakable.
const d = $input.first().json;
return [{ json: {
  status: 'SCRAPER_ALERT',
  reason: (d && d.reason) || 'Upstream fetch failed after retries',
  at: new Date().toISOString(),
} }];
